1	/*
2	 * MPU6050 -> AI Thinker ESP32-CAM -> raw sensor data over UDP on WiFi
3	 * -------------------------------------------------------------------
4	 * BOARD: "AI Thinker ESP32-CAM" (esp32 core 3.x).
5	 * SETUP: copy config.example.h to config.h in this folder and fill in your WiFi
6	 * details. Git ignores config.h, so your password stays on your computer.
7	 * The camera on the board is not used.
8	 *
9	 * WIRING:
10	 *   MPU6050 VCC -> ESP32-CAM 3V3
11	 *   MPU6050 GND -> ESP32-CAM GND
12	 *   MPU6050 SDA -> ESP32-CAM pin set in MPU_SDA_PIN (default GPIO13)
13	 *   MPU6050 SCL -> ESP32-CAM pin set in MPU_SCL_PIN (default GPIO14)
14	 *   Power the ESP32-CAM from a solid 5 V supply, because WiFi draws current spikes
15	 *   that can reset the board on a weak one.
16	 *
17	 * CHOOSING PINS:
18	 *   GPIO13 and GPIO14 are the best choice, and are only shared with the SD card slot.
19	 *   Avoid GPIO12, GPIO15, GPIO2 and GPIO0, which affect booting if held high or low at
20	 *   power on, and GPIO16, which is used by PSRAM. GPIO1 and GPIO3 are the USB serial
21	 *   pins, and GPIO4 drives the flash LED.
22	 *
23	 * UDP STREAM:
24	 *   Sent to port UDP_PORT, at LAPTOP_IP if set, otherwise broadcast to the whole network.
25	 *   Each packet holds FRAMES_PER_PACKET frames, one after another, in this 19-byte format:
26	 *   0xA5 0x5A | timestamp in microseconds (uint32, little-endian)
27	 *   | ax ay az gx gy gz (int16, big-endian) | XOR of timestamp and sensor bytes
28	 *
29	 * SENSOR SETTINGS:
30	 *   Accel +-16 g (2048 LSB/g), gyro +-2000 deg/s (16.4 LSB per deg/s), 500 Hz.
31	 */
32	
33	#include <WiFi.h>
34	#include <WiFiUdp.h>
35	#include <Wire.h>
36	
37	#include "config.h"  // WIFI_SSID, WIFI_PASSWORD and LAPTOP_IP
38	
39	// ---------------- USER CONFIGURATION ----------------
40	
41	int MPU_SDA_PIN = 13;
42	int MPU_SCL_PIN = 14;
43	
44	const uint16_t UDP_PORT = 5005;
45	// ------------------------------------------------------
46	
47	const int STATUS_LED_PIN = 33;  // small red LED on the back of the board, on when driven LOW
48	
49	const uint8_t MPU6050_ADDR = 0x68;  // change to 0x69 if AD0 pin is pulled high
50	const uint32_t I2C_CLOCK_HZ = 400000;
51	const uint16_t I2C_TIMEOUT_MS = 5;
52	
53	const int FRAMES_PER_PACKET = 10;  // 10 frames at 500 Hz = 50 packets/s and 20 ms of delay
54	const int QUEUE_FRAMES = 100;
55	const uint32_t STATUS_PERIOD_MS = 5000;
56	const uint32_t CONFIG_CHECK_MS = 250;
57	const TickType_t SAMPLE_PERIOD_TICKS = pdMS_TO_TICKS(2);  // 500 Hz
58	
59	const int FRAME_SIZE = 19;
60	
61	const uint8_t REG_SMPLRT_DIV = 0x19;
62	const uint8_t REG_CONFIG = 0x1A;
63	const uint8_t REG_GYRO_CONFIG = 0x1B;
64	const uint8_t REG_ACCEL_CONFIG = 0x1C;
65	const uint8_t REG_ACCEL_XOUT_H = 0x3B;
66	const uint8_t REG_PWR_MGMT_1 = 0x6B;
67	
68	const uint8_t PWR_MGMT_1_VALUE = 0x01;    // wake up, use gyro clock
69	const uint8_t ACCEL_CONFIG_VALUE = 0x18;  // +-16 g
70	
71	QueueHandle_t frameQueue;
72	volatile uint32_t samplesRead = 0;
73	volatile uint32_t samplesDropped = 0;
74	volatile uint32_t sensorErrors = 0;
75	volatile uint32_t packetsSent = 0;
76	
77	bool writeRegister(uint8_t reg, uint8_t value) {
78	  Wire.beginTransmission(MPU6050_ADDR);
79	  Wire.write(reg);
80	  Wire.write(value);
81	  return Wire.endTransmission() == 0;
82	}
83	
84	int readRegister(uint8_t reg) {
85	  Wire.beginTransmission(MPU6050_ADDR);
86	  Wire.write(reg);
87	  if (Wire.endTransmission(false) != 0 || Wire.requestFrom(MPU6050_ADDR, (uint8_t)1) != 1) {
88	    return -1;
89	  }
90	  return Wire.read();
91	}
92	
93	bool configureSensor() {
94	  return writeRegister(REG_PWR_MGMT_1, PWR_MGMT_1_VALUE)
95	      && writeRegister(REG_CONFIG, 0x01)         // 184 Hz low-pass, 1 kHz base rate
96	      && writeRegister(REG_SMPLRT_DIV, 0x01)     // 1 kHz / (1 + 1) = 500 Hz
97	      && writeRegister(REG_GYRO_CONFIG, 0x18)    // +-2000 deg/s
98	      && writeRegister(REG_ACCEL_CONFIG, ACCEL_CONFIG_VALUE);
99	}
100	
101	// A power blip from an impact resets the sensor to asleep at +-2 g, while the ESP32
102	// keeps running. Its readings then look wrong forever, so check and set it up again.
103	void restoreSensorIfReset() {
104	  static uint32_t lastCheckMs = 0;
105	  if (millis() - lastCheckMs < CONFIG_CHECK_MS) {
106	    return;
107	  }
108	  lastCheckMs = millis();
109	  if (readRegister(REG_PWR_MGMT_1) != PWR_MGMT_1_VALUE
110	      || readRegister(REG_ACCEL_CONFIG) != ACCEL_CONFIG_VALUE) {
111	    configureSensor();
112	  }
113	}
114	
115	bool readFrame(uint8_t* frame) {
116	  uint32_t timestamp = micros();
117	
118	  Wire.beginTransmission(MPU6050_ADDR);
119	  Wire.write(REG_ACCEL_XOUT_H);
120	  if (Wire.endTransmission(false) != 0 || Wire.requestFrom(MPU6050_ADDR, (uint8_t)14) != 14) {
121	    return false;
122	  }
123	
124	  // Layout: accel[0..5], temperature[6..7], gyro[8..13]
125	  uint8_t raw[14];
126	  for (uint8_t i = 0; i < 14; i++) {
127	    raw[i] = Wire.read();
128	  }
129	
130	  frame[0] = 0xA5;
131	  frame[1] = 0x5A;
132	  frame[2] = timestamp & 0xFF;
133	  frame[3] = (timestamp >> 8) & 0xFF;
134	  frame[4] = (timestamp >> 16) & 0xFF;
135	  frame[5] = (timestamp >> 24) & 0xFF;
136	  memcpy(&frame[6], &raw[0], 6);
137	  memcpy(&frame[12], &raw[8], 6);
138	
139	  uint8_t checksum = 0;
140	  for (uint8_t i = 2; i < 18; i++) {
141	    checksum ^= frame[i];
142	  }
143	  frame[18] = checksum;
144	  return true;
145	}
146	
147	// Runs on core 1, away from the WiFi stack on core 0, to keep sampling regular
148	void sensorTask(void*) {
149	  TickType_t lastWake = xTaskGetTickCount();
150	  uint8_t frame[FRAME_SIZE];
151	  while (true) {
152	    vTaskDelayUntil(&lastWake, SAMPLE_PERIOD_TICKS);
153	    restoreSensorIfReset();
154	    if (!readFrame(frame)) {
155	      sensorErrors = sensorErrors + 1;
156	      continue;
157	    }
158	    samplesRead = samplesRead + 1;
159	    if (xQueueSend(frameQueue, frame, 0) != pdTRUE) {
160	      samplesDropped = samplesDropped + 1;
161	    }
162	  }
163	}
164	
165	void networkTask(void*) {
166	  WiFiUDP udp;
167	  IPAddress laptop;
168	  bool useLaptopIp = laptop.fromString(LAPTOP_IP);
169	
170	  uint8_t packet[FRAMES_PER_PACKET * FRAME_SIZE];
171	  int framesInPacket = 0;
172	  while (true) {
173	    xQueueReceive(frameQueue, &packet[framesInPacket * FRAME_SIZE], portMAX_DELAY);
174	    framesInPacket++;
175	    if (framesInPacket < FRAMES_PER_PACKET) {
176	      continue;
177	    }
178	    framesInPacket = 0;
179	    if (WiFi.status() != WL_CONNECTED) {
180	      continue;
181	    }
182	    if (udp.beginPacket(useLaptopIp ? laptop : WiFi.broadcastIP(), UDP_PORT)) {
183	      udp.write(packet, sizeof(packet));
184	      if (udp.endPacket()) {
185	        packetsSent = packetsSent + 1;
186	      }
187	    }
188	  }
189	}
190	
191	void setup() {
192	  pinMode(STATUS_LED_PIN, OUTPUT);
193	  digitalWrite(STATUS_LED_PIN, LOW);
194	
195	  Serial.begin(115200);
196	  Serial.println();
197	
198	  if (strlen(WIFI_SSID) == 0) {
199	    Serial.println("ERROR: WIFI_SSID is empty. Fill in the WiFi details in config.h.");
200	    while (true) {
201	      delay(1000);
202	    }
203	  }
204	
205	  Wire.begin(MPU_SDA_PIN, MPU_SCL_PIN, I2C_CLOCK_HZ);
206	  Wire.setTimeOut(I2C_TIMEOUT_MS);
207	  if (!configureSensor()) {
208	    Serial.printf("ERROR: MPU6050 not found on SDA GPIO%d, SCL GPIO%d. Still retrying.\n", MPU_SDA_PIN, MPU_SCL_PIN);
209	  }
210	
211	  WiFi.mode(WIFI_STA);
212	  WiFi.setSleep(false);  // WiFi power saving adds around 100 ms of delay
213	  WiFi.setAutoReconnect(true);
214	  WiFi.begin(WIFI_SSID, WIFI_PASSWORD);
215	  Serial.printf("Connecting to %s", WIFI_SSID);
216	  while (WiFi.status() != WL_CONNECTED) {
217	    delay(250);
218	    Serial.print(".");
219	  }
220	  Serial.printf("\nConnected. IP address: %s\n", WiFi.localIP().toString().c_str());
221	  Serial.printf("Sending UDP to %s port %u\n",
222	                strlen(LAPTOP_IP) > 0 ? LAPTOP_IP : WiFi.broadcastIP().toString().c_str(), UDP_PORT);
223	
224	  frameQueue = xQueueCreate(QUEUE_FRAMES, FRAME_SIZE);
225	  xTaskCreatePinnedToCore(networkTask, "network", 4096, nullptr, 2, nullptr, 0);
226	  xTaskCreatePinnedToCore(sensorTask, "sensor", 4096, nullptr, 5, nullptr, 1);
227	}
228	
229	void loop() {
230	  static uint32_t lastSamples = 0;
231	  static uint32_t lastErrors = 0;
232	  delay(STATUS_PERIOD_MS);
233	  uint32_t samples = samplesRead;
234	  uint32_t errors = sensorErrors;
235	  Serial.printf("Sensor %lu Hz, %lu read errors | %lu packets sent, %lu samples dropped | RSSI %d dBm\n",
236	                (unsigned long)((samples - lastSamples) * 1000 / STATUS_PERIOD_MS),
237	                (unsigned long)(errors - lastErrors),
238	                (unsigned long)packetsSent, (unsigned long)samplesDropped, WiFi.RSSI());
239	  lastSamples = samples;
240	  lastErrors = errors;
241	}
