2	 * MPU6050 -> Arduino Uno -> High-speed binary stream for punch_tracker.py
3	 * -----------------------------------------------------------------------
4	 * LIBRARIES NEEDED:
5	 *   - Wire.h  (built into the Arduino IDE, no install needed)
6	 *
7	 * WIRING:
8	 *   MPU6050 VCC -> Arduino 5V (or 3.3V, check your board)
9	 *   MPU6050 GND -> Arduino GND
10	 *   MPU6050 SCL -> Arduino A5 (Uno hardware I2C clock pin)
11	 *   MPU6050 SDA -> Arduino A4 (Uno hardware I2C data pin)
12	 *
13	 * USAGE:
14	 *   Upload this sketch, close the Serial Monitor and Serial Plotter, then run
15	 *   punch_tracker.py. The output is binary, so it looks like garbage in the
16	 *   Serial Monitor. If the sensor is not found, an error message is printed
17	 *   instead, which is readable in the Serial Monitor at SERIAL_BAUD.
18	 *
19	 * FRAME FORMAT (19 bytes):
20	 *   0xA5 0x5A | timestamp in microseconds (uint32, little-endian)
21	 *   | ax ay az gx gy gz (int16, big-endian) | XOR of timestamp and sensor bytes
22	 *
23	 * SENSOR SETTINGS:
24	 *   Accel +-16 g (2048 LSB/g), gyro +-2000 deg/s (16.4 LSB per deg/s).
25	 *   If you change these, change the matching constants in punch_tracker.py.
26	 */
27	
28	#include <Wire.h>
29	
30	// ---------------- USER CONFIGURATION ----------------
31	#define MPU6050_ADDR 0x68      // change to 0x69 if AD0 pin is pulled high
32	#define SERIAL_BAUD 500000     // must match --baud in punch_tracker.py
33	#define SAMPLE_PERIOD_US 2000  // 2000 us = 500 Hz
34	// ------------------------------------------------------
35	
36	#define REG_SMPLRT_DIV   0x19
37	#define REG_CONFIG       0x1A
38	#define REG_GYRO_CONFIG  0x1B
39	#define REG_ACCEL_CONFIG 0x1C
40	#define REG_ACCEL_XOUT_H 0x3B
41	#define REG_PWR_MGMT_1   0x6B
42	
43	#define WIRE_TIMEOUT_US 3000
44	#define CONFIG_CHECK_US 250000UL
45	#define PWR_MGMT_1_VALUE 0x01    // wake up, use gyro clock
46	#define ACCEL_CONFIG_VALUE 0x18  // +-16 g
47	
48	unsigned long nextSampleMicros;
49	unsigned long lastConfigCheckMicros;
50	
51	bool writeRegister(uint8_t reg, uint8_t value) {
52	  Wire.beginTransmission(MPU6050_ADDR);
53	  Wire.write(reg);
54	  Wire.write(value);
55	  return Wire.endTransmission() == 0;
56	}
57	
58	int readRegister(uint8_t reg) {
59	  Wire.beginTransmission(MPU6050_ADDR);
60	  Wire.write(reg);
61	  if (Wire.endTransmission(false) != 0 || Wire.requestFrom(MPU6050_ADDR, 1, true) != 1) {
62	    return -1;
63	  }
64	  return Wire.read();
65	}
66	
67	bool configureSensor() {
68	  return writeRegister(REG_PWR_MGMT_1, PWR_MGMT_1_VALUE)
69	      && writeRegister(REG_CONFIG, 0x01)         // 184 Hz low-pass, 1 kHz base rate
70	      && writeRegister(REG_SMPLRT_DIV, 0x01)     // 1 kHz / (1 + 1) = 500 Hz
71	      && writeRegister(REG_GYRO_CONFIG, 0x18)    // +-2000 deg/s
72	      && writeRegister(REG_ACCEL_CONFIG, ACCEL_CONFIG_VALUE);
73	}
74	
75	// A power blip from an impact resets the sensor to asleep at +-2 g, while the Uno keeps
76	// running. Its readings then look wrong forever, so check for that and set it up again.
77	void restoreSensorIfReset() {
78	  if (micros() - lastConfigCheckMicros < CONFIG_CHECK_US) {
79	    return;
80	  }
81	  lastConfigCheckMicros = micros();
82	  if (readRegister(REG_PWR_MGMT_1) != PWR_MGMT_1_VALUE
83	      || readRegister(REG_ACCEL_CONFIG) != ACCEL_CONFIG_VALUE) {
84	    configureSensor();
85	  }
86	}
87	
88	void setup() {
89	  Serial.begin(SERIAL_BAUD);
90	  Wire.begin();
91	  Wire.setClock(400000);
92	  // Impacts can jolt the wiring, and without a timeout a bad connection hangs I2C forever
93	  Wire.setWireTimeout(WIRE_TIMEOUT_US, true);
94	
95	  while (!configureSensor()) {
96	    Serial.println("ERROR: MPU6050 not found. Check wiring and MPU6050_ADDR.");
97	    delay(1000);
98	  }
99	
100	  delay(100);
101	  nextSampleMicros = micros();
102	  lastConfigCheckMicros = nextSampleMicros;
103	}
104	
105	void loop() {
106	  if ((long)(micros() - nextSampleMicros) < 0) {
107	    return;
108	  }
109	  nextSampleMicros += SAMPLE_PERIOD_US;
110	
111	  restoreSensorIfReset();
112	
113	  uint32_t timestamp = micros();
114	
115	  Wire.beginTransmission(MPU6050_ADDR);
116	  Wire.write(REG_ACCEL_XOUT_H);
117	  if (Wire.endTransmission(false) != 0) {
118	    return;
119	  }
120	  if (Wire.requestFrom(MPU6050_ADDR, 14, true) != 14) {
121	    return;
122	  }
123	
124	  // Layout: accel[0..5], temperature[6..7], gyro[8..13]
125	  uint8_t raw[14];
126	  for (uint8_t i = 0; i < 14; i++) {
127	    raw[i] = Wire.read();
128	  }
129	
130	  uint8_t frame[19];
131	  frame[0] = 0xA5;
132	  frame[1] = 0x5A;
133	  frame[2] = timestamp & 0xFF;
134	  frame[3] = (timestamp >> 8) & 0xFF;
135	  frame[4] = (timestamp >> 16) & 0xFF;
136	  frame[5] = (timestamp >> 24) & 0xFF;
137	  memcpy(&frame[6], &raw[0], 6);
138	  memcpy(&frame[12], &raw[8], 6);
139	
140	  uint8_t checksum = 0;
141	  for (uint8_t i = 2; i < 18; i++) {
142	    checksum ^= frame[i];
143	  }
144	  frame[18] = checksum;
145	
146	  Serial.write(frame, sizeof(frame));
147	}
